const MESSAGES = { en, am, om };

/** 'am-ET' / 'AM' / undefined -> 'am' | 'om' | 'en'. */
const normalizeLocale = (locale) => {
  const base = String(locale || '').toLowerCase().slice(0, 2);
  return SUPPORTED.includes(base) ? base : 'en';
};

/** Locale of a pharmacy document (settings.locale), default 'en'. */
const pharmacyLocale = (pharmacy) => normalizeLocale(pharmacy && pharmacy.settings && pharmacy.settings.locale);

const interpolate = (str, vars) =>
  str.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, name) => (vars && vars[name] !== undefined && vars[name] !== null ? String(vars[name]) : ''));

const t = (locale, key, vars = {}) => {
  const loc = normalizeLocale(locale);
  const table = MESSAGES[loc];
  const candidates = [];
  if (vars && typeof vars.count === 'number') {
    const plural = `${key}_${vars.count === 1 ? 'one' : 'other'}`;
    candidates.push([table, plural], [table, key], [en, plural], [en, key]);
  } else {
    candidates.push([table, key], [en, key]);
  }
  for (const [tbl, k] of candidates) {
    if (typeof tbl[k] === 'string') return interpolate(tbl[k], vars);
  }
  return key;
};

/**
 * Calendar date for outgoing texts: 'YYYY-MM-DD' (UTC day) for en/om; for am the same
 * date followed by the Ethiopian calendar date, e.g. "2024-09-11 (መስከረም 1, 2017 ዓ.ም.)".
 * Options: gregorian = an already formatted Gregorian string to use instead (e.g. with a
 * time part); utc = false to take the server-local calendar day for the Ethiopian date.
 */
const localDate = (locale, date, { gregorian, utc = true } = {}) => {
  const d = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(d.getTime())) return gregorian || '';
  const iso = gregorian || d.toISOString().slice(0, 10);
  if (normalizeLocale(locale) !== 'am') return iso;
  const et = formatEthiopianDate(d, 'am', { utc });
  return et ? `${iso} (${et})` : iso;
};

module.exports = { t, normalizeLocale, pharmacyLocale, localDate, MESSAGES, SUPPORTED };
